//! 🧵️ Original text and admitted Unicode records resolve canonical scalars without replacing source custody.
use super::{UnicodeLayout,UnicodeMapping,UnicodeMappingCursor,UnicodePropertyCursor};
use semio_framework_2d_text_font::{FontReader,FontProgress};
use semio_framework_value::retirement::{RetireOwned, RetirementCursor};
use semio_framework_value_persistent::list::PagedList;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct NormalizedScalar{pub scalar:u32,pub source_at:usize,pub combining_class:u8}
semio_framework_value::artifact_retire_leaf!(NormalizedScalar);
#[derive(Clone,Copy,Default)]
struct Pending{scalar:u32,source_at:usize,depth:u8}
#[derive(semio_framework_value::RetireOwned)]
struct Owners{scratch:PagedList<NormalizedScalar,{usize::MAX}>,output:Option<PagedList<NormalizedScalar,{usize::MAX}>>,failure:Option<&'static str>}
pub struct UnicodeNormalizationCursor{owners:Owners,layout:UnicodeLayout,text_pointer:usize,text_bytes:usize,data_pointer:usize,max_scalars:usize,max_work:u64,phase:u8,source_at:usize,work:u64,cancelled:bool,stack:[Pending;256],stack_len:usize,current:Pending,mapping:Option<UnicodeMappingCursor>,property:Option<UnicodePropertyCursor>,expand_first:usize,expand_at:usize,order_at:usize,compose_at:usize,starter:Option<usize>,previous_class:u8,hangul:[u32;3],combining_class:u8}
impl RetireOwned for UnicodeNormalizationCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl UnicodeNormalizationCursor{
 pub fn new(layout:UnicodeLayout,bytes:&[u8],text:&str,max_scalars:usize,max_work:u64)->Self{let invalid=bytes.len()!=layout.byte_length||!(1..=1048576).contains(&max_scalars)||!(1..=1000000000).contains(&max_work);Self{owners:Owners{scratch:PagedList::new(),output:Some(PagedList::new()),failure:invalid.then(||"Invalid canonical normalization limits".into())},layout,text_pointer:text.as_ptr()as usize,text_bytes:text.len(),data_pointer:bytes.as_ptr()as usize,max_scalars,max_work,phase:0,source_at:0,work:0,cancelled:false,stack:[Pending::default();256],stack_len:0,current:Pending::default(),mapping:None,property:None,expand_first:0,expand_at:0,order_at:0,compose_at:0,starter:None,previous_class:0,hangul:[0;3],combining_class:0}}
 fn push(&mut self,scalar:u32,source_at:usize,depth:u8)->Result<(),&'static str>{if depth>32||self.stack_len==256{return Err("Canonical decomposition depth exceeded".into());}self.stack[self.stack_len]=Pending{scalar,source_at,depth};self.stack_len+=1;Ok(())}
 fn hangul_compose(first:u32,second:u32)->Option<u32>{if(0x1100..0x1113).contains(&first)&&(0x1161..0x1176).contains(&second){Some(0xac00+(first-0x1100)*588+(second-0x1161)*28)}else if(0xac00..0xd7a4).contains(&first)&&(first-0xac00)%28==0&&(0x11a8..0x11c3).contains(&second){Some(first+second-0x11a7)}else{None}}
 fn combine(&mut self,scalar:u32,work:&mut semio_framework_2d_text_font::work::FontWorkLedger)->Result<(),&'static str>{if !work.copy_bytes(std::mem::size_of::<NormalizedScalar>()){return Ok(());}let current=*self.owners.scratch.get(self.compose_at).ok_or("Canonical candidate missing")?;let value=self.owners.output.as_mut().unwrap().get_mut(self.starter.ok_or("Canonical starter missing")?).ok_or("Canonical starter missing")?;value.scalar=scalar;value.source_at=value.source_at.min(current.source_at);self.compose_at+=1;self.phase=6;Ok(())}
 fn step(&mut self,bytes:&[u8],text:&str,work:&mut semio_framework_2d_text_font::work::FontWorkLedger)->Result<(),&'static str>{if !work.can_step(){return Ok(());}if bytes.len()!=self.layout.byte_length||bytes.as_ptr()as usize!=self.data_pointer||text.len()!=self.text_bytes||text.as_ptr()as usize!=self.text_pointer{return Err("Captured canonical source changed".into());}let r=FontReader::whole(bytes);match self.phase{
  0=>{if self.stack_len>0{self.stack_len-=1;self.current=self.stack[self.stack_len];let value=self.current.scalar;if(0xac00..0xd7a4).contains(&value){let s=value-0xac00;let t=s%28;self.hangul=[0x1100+s/588,0x1161+(s%588)/28,0x11a7+t];self.expand_at=if t==0{2}else{3};self.phase=1;}else{self.mapping=Some(UnicodeMappingCursor::new(self.layout,UnicodeMapping::Decomposition,value,0));self.phase=2;}return Ok(());}if self.source_at==text.len(){self.phase=6;return Ok(());}let scalar=text.get(self.source_at..).and_then(|tail|tail.chars().next()).ok_or("Canonical scalar boundary invalid")?;self.push(scalar as u32,self.source_at,0)?;self.source_at+=scalar.len_utf8();},
  1=>{if self.expand_at>0{self.expand_at-=1;self.push(self.hangul[self.expand_at],self.current.source_at,self.current.depth+1)?;}else{self.phase=0;}},
  2=>{if !self.mapping.as_mut().unwrap().step(bytes,work)?{return Ok(());}let at=self.mapping.as_ref().unwrap().result()?;self.mapping=None;if let Some(at)=at.filter(|at|r.u32(at+12).ok()==Some(0)){self.expand_first=r.u32(at+4)?as usize;self.expand_at=r.u32(at+8)?as usize;self.phase=3;}else{self.property=Some(UnicodePropertyCursor::new(self.layout,self.current.scalar)?);self.phase=4;}},
  3=>{if self.expand_at>0{self.expand_at-=1;self.push(r.u32(self.layout.offsets[3]+(self.expand_first+self.expand_at)*4)?,self.current.source_at,self.current.depth+1)?;}else{self.phase=0;}},
  4=>{if !self.property.as_mut().unwrap().step(bytes,work)?{return Ok(());}self.combining_class=self.property.as_ref().unwrap().result()?.combining_class;self.property=None;self.phase=5;},
  5=>{if self.owners.scratch.len()==self.max_scalars{return Err("Canonical scalar limit exceeded".into());}if !work.slot(&mut self.owners.scratch)?{return Ok(());}work.push(&mut self.owners.scratch,NormalizedScalar{scalar:self.current.scalar,source_at:self.current.source_at,combining_class:self.combining_class}).map_err(|_|"Canonical reservation lost")?;self.order_at=self.owners.scratch.len()-1;self.phase=9;},
  9=>{let values=&mut self.owners.scratch;if self.order_at>0&&values.get(self.order_at).unwrap().combining_class!=0&&values.get(self.order_at-1).unwrap().combining_class>values.get(self.order_at).unwrap().combining_class{if !work.copy_bytes(2*std::mem::size_of::<NormalizedScalar>()){return Ok(());}values.swap(self.order_at,self.order_at-1);self.order_at-=1;}else{self.phase=0;}},
  6=>{if self.compose_at==self.owners.scratch.len(){self.phase=10;return Ok(());}let current=*self.owners.scratch.get(self.compose_at).unwrap();if let Some(starter)=self.starter.filter(|_|self.previous_class==0||self.previous_class<current.combining_class){let first=self.owners.output.as_ref().unwrap().get(starter).unwrap().scalar;if let Some(value)=Self::hangul_compose(first,current.scalar){self.combine(value,work)?;return Ok(());}self.mapping=Some(UnicodeMappingCursor::new(self.layout,UnicodeMapping::Composition,first,current.scalar));self.phase=7;}else{self.phase=8;}},
  7=>{if !self.mapping.as_mut().unwrap().step(bytes,work)?{return Ok(());}let at=self.mapping.as_ref().unwrap().result()?;if let Some(at)=at{self.combine(r.u32(at+8)?,work)?;if !work.blocked(){self.mapping=None;}}else{self.mapping=None;self.phase=8;}},
  8=>{let output=self.owners.output.as_mut().unwrap();if !work.slot(output)?{return Ok(());}let current=*self.owners.scratch.get(self.compose_at).unwrap();work.push(output,current).map_err(|_|"Canonical output reservation lost")?;if current.combining_class==0{self.starter=Some(output.len()-1);}self.previous_class=current.combining_class;self.compose_at+=1;self.phase=6;},
  _=>return Err("Canonical normalization stage invalid".into()),
 }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],text:&str,grant:usize,work:&mut semio_framework_2d_text_font::work::FontWorkLedger)->Result<FontProgress,&'static str>{let entered=work.enter();let result=(||{if grant==0{return Err("Invalid canonical work grant".into());}if self.cancelled{return Err("Canonical normalization cancelled".into());}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..(if entered.is_some(){grant.min(work.remaining().maximum_items)}else{0}){if self.phase==10{break;}if self.work==self.max_work{self.owners.failure=Some("Canonical work limit exceeded".into());return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes,text,work){self.owners.failure=Some(error.clone());return Err(error);}if work.blocked(){break;}self.work+=1;work.note_source(entered==Some(true));}Ok(FontProgress{phase:match self.phase{0=>"read",1=>"hangul",2=>"decompose",3=>"expand",4=>"property",5=>"reserve",6=>"compose",7=>"composition",8=>"append",9=>"order",_=>"complete"},work:self.work,done:self.phase==10})})();if entered.is_some(){work.exit();}result}
 pub fn result(&self)->Result<&PagedList<NormalizedScalar,{usize::MAX}>,&'static str>{if self.phase!=10||self.cancelled||self.owners.failure.is_some(){return Err("Canonical normalization incomplete".into());}self.owners.output.as_ref().ok_or_else(||"Canonical output transferred".into())}
 pub fn take_result(&mut self)->Result<PagedList<NormalizedScalar,{usize::MAX}>,&'static str>{self.result()?;Ok(self.owners.output.take().unwrap())}
 pub fn cancel(&mut self){self.cancelled=true;}
}
